        { type = "travel", name = "Talk to Osborne the Night Man", note = "BE VERY CAREFUL with your money management in the coming steps. Only buy essential spells. You will need 75 silver to obtain a rune after a couple quests in wetlands - Train [Vanish] and [Stealth](rank 2) You will need it to unlock [Deadly Brew] soon - Train [Vanish] - Train [Stealth](rank 2)", zone = "Stormwind City", x = 74.65, y = 52.83, npc = "Osborne the Night Man", class = "ROGUE" },
