        { type = "complete", name = "Kill Dust Devils. Loot them for their Debris", note = "Dust Devils can spawn throughout all of Westfall. Their spawn locations are marked on the map - Cast [Eagle Eye] to try and find them - .unitscan Dust Devil - .isOnQuest 1076", zone = "Westfall", x = 34.8, y = 67.4, quest = 1076, objective = 1, path = { { zone = "Westfall", x = 63.6, y = 51.4 }, { zone = "Westfall", x = 60.6, y = 34 }, { zone = "Westfall", x = 45.4, y = 49.6 }, { zone = "Westfall", x = 63.8, y = 52 }, { zone = "Westfall", x = 61.8, y = 34.4 }, { zone = "Westfall", x = 54.6, y = 41 }, { zone = "Westfall", x = 46.8, y = 48.6 }, { zone = "Westfall", x = 43.6, y = 42 }, { zone = "Westfall", x = 41, y = 21 }, { zone = "Westfall", x = 35.8, y = 34.4 }, { zone = "Westfall", x = 33.8, y = 50.6 }, { zone = "Westfall", x = 42.6, y = 60.2 }, { zone = "Westfall", x = 38.8, y = 61.4 } } },
