        { type = "note", name = "Press Escape, then go into -> Options -> Controls", note = "==PAY ATTENTION TO THE UPCOMING SECTION== - Check \"Enable Interact Key\" and bind the \"Interact with Target\" option to a key - Additionally, it's recommended you enable Enemy Nameplates (Default Key: V) as it allows you to see enemies behind some of the corners inside the tower", class = "ROGUE" },
        { type = "accept", name = "Talk to Agent Kearnen", note = "You MUST do this quest your [Poisons]", zone = "Westfall", x = 68.5, y = 70.08, npc = "Agent Kearnen", quest = 2359, class = "ROGUE" },
        { type = "complete", name = "[Pick Pocket] the Malformed Defias Drone. Loot it for the Defias Tower Key", note = "You must be in [Stealth] to use [Pick Pocket] - The |cRXP_ENEMY_Malformed Defias Drone spawns at the entrance to the tower, then patrols around the outside of it - Be careful as he deals a LOT of damage. If your [Stealth] breaks, quickly use [Sprint] and run away - .mob Malformed Defias Drone", zone = "Westfall", x = 69.58, y = 73.07, quest = 2359, objective = 2, class = "ROGUE", path = { { zone = "Westfall", x = 71.49, y = 73.49 }, { zone = "Westfall", x = 71.01, y = 75.72 }, { zone = "Westfall", x = 69.58, y = 73.07 }, { zone = "Westfall", x = 71.49, y = 73.49 }, { zone = "Westfall", x = 71.01, y = 75.72 } } },
        { type = "note", name = "Equip the [Curvewood Dagger] for this quest if you don't already have a [Dagger] equipped - .use 15396 - .itemcount 15396,1", note = "Equip the [Curvewood Dagger] for this quest if you don't already have a [Dagger] equipped - .use 15396 - .itemcount 15396,1", class = "ROGUE" },
        { type = "complete", name = "Travel up to 2nd top floor of the tower. Whilst in [Stealth] and the |cRXP_ENEMY_Defias Tower Sentries aren't next to you, Jump onto the chair, then onto the lamp, then onto the bookshelf on top of the waypoint location", note = "Manually [Unstealth], then press your \"Interact with Target\" keybind to open the |cRXP_PICK_Duskwood Chest. Loot it for Klaven Mortwake's Journal - NOTE: Your [Stealth] will temporarily stop working after looting Klaven Mortwake's Journal - Be prepared to run if you don't kill the |cRXP_ENEMY_Defias Tower Sentries on the 2nd floor. They will most likely aggro you permanently (but not attack you) when you are on top of the bookshelf as it is an evade spot - If you have a [Dagger] in your bags or equipped, you can cast [Ambush] on the |cRXP_ENEMY_Defias Tower Patrollers and Defias Tower Sentries inside to kill them instantly. Be prepared to run after you kill the first Defias Tower Sentry and remember you can be hit from above. This is slower, but a LOT safer - Be careful as the |cRXP_ENEMY_Malformed Defias Drone and Defias Drones can be at the entrance of the tower if you have to run out of it - .mob Defias Tower Patroller - .mob Defias Tower Sentry", map = 1436, x = 70.421, y = 74.031, quest = 2359, objective = 1, class = "ROGUE" },
        { type = "note", name = "Cast [Stoneform] to remove the [Touch of Zanzil] debuff - .aura -9991", note = "Cast [Stoneform] to remove the [Touch of Zanzil] debuff - .aura -9991", class = "ROGUE", optional = true, races = { "Dwarf" } },
