        { type = "travel", name = "Kill Nightbane Worgens. Loot them for [An Old History Book]", note = "Don't start the quest for it yet - .collect 2794,1,337 - .mob Nightbane Shadow Weaver - .mob Nightbane Dark Runner - .mob Nightbane Tainted One - .mob Nightbane Worgen", zone = "Duskwood", x = 64.14, y = 68.49, path = { { zone = "Duskwood", x = 62.33, y = 81.77 }, { zone = "Duskwood", x = 61.3, y = 74.36 }, { zone = "Duskwood", x = 65.1, y = 73.91 } } },
        { type = "complete", name = "Kill Nightbane Vile Fangs and Nightbane Tainted Ones", note = "Be careful as all the mobs in the area respawn at once after 4.75-6.5 minutes of killing the first one - This area is a popular grinding spot for mages and may be constested. If you feel like there's too much competition you can complete this objective in the Roland's Doom area (cave, marked on your map) - .mob +Nightbane Vile Fang - .mob +Nightbane Tainted One", zone = "Duskwood", x = 71.9, y = 72.1, quest = 222, objective = 2, path = { { zone = "Duskwood", x = 62.33, y = 81.77 } } },
        { type = "grind", name = "Grind until 43180/50800 xp into level 31", note = "Kill Nightbane Worgens until your Hearthstone cooldown is <25 minutes - If you know that you will be leveling in one session or generally not getting a lot of rested experience up to level 38, consider grinding to level 32 instead. This will help you reach a level 38 xp gate that is required later on - .mob Nightbane Shadow Weaver - .mob Nightbane Dark Runner - .mob Nightbane Tainted One - .mob Nightbane Worgen", zone = "Duskwood", x = 64.14, y = 68.49, targetLevel = 31, path = { { zone = "Duskwood", x = 62.33, y = 81.77 }, { zone = "Duskwood", x = 61.3, y = 74.36 }, { zone = "Duskwood", x = 65.1, y = 73.91 } } },
        { type = "travel", name = "Keep killing Nightbane Worgens. Untill you loot [An Old History Book]", note = "Don't start the quest for it yet - .collect 2794,1,337 - .mob Nightbane Shadow Weaver - .mob Nightbane Dark Runner - .mob Nightbane Tainted One - .mob Nightbane Worgen", zone = "Duskwood", x = 64.14, y = 68.49, path = { { zone = "Duskwood", x = 62.33, y = 81.77 }, { zone = "Duskwood", x = 61.3, y = 74.36 }, { zone = "Duskwood", x = 65.1, y = 73.91 } } },
        { type = "travel", name = "This step will autocomplete when your HS cooldown is low enough to continue", note = "Keep killing Nightbane Worgens until your Hearthstone cooldown is <25 minutes - .cooldown item,6948,<1500 - .mob Nightbane Shadow Weaver - .mob Nightbane Dark Runner - .mob Nightbane Tainted One - .mob Nightbane Worgen", zone = "Duskwood", x = 64.14, y = 68.49, path = { { zone = "Duskwood", x = 62.33, y = 81.77 }, { zone = "Duskwood", x = 61.3, y = 74.36 }, { zone = "Duskwood", x = 65.1, y = 73.91 } } },
        { type = "complete", name = "Click Eliza's Grave Dirt to summon Eliza", note = "Kill Eliza. Loot her for the Embalmer's Heart - Eliza will cast [Frostbolt] and [Frost Nova] along with summoning multiple Guards - You can avoid dealing with |cRXP_ENEMY_Eliza's Guards by using the Wagon to jump on top of Abercrombie's Hut - You can evade |cRXP_ENEMY_Eliza's Guards by using the Wagon to jump on top of Abercrombie's Hut. Eliza will continue to cast [Frostbolt] at you if you do this while she's alive - .mob Eliza", zone = "Duskwood", x = 28.864, y = 30.765, quest = 253, objective = 1 },
        { type = "note", name = "Clear your way to the 2nd floor of the house", note = "Equip [Morbent's Bane] in your off-hand - Use [Morbent's Bane] on Morbent Fel to weaken him - Remember to equip your weapon/off-hand slot after weakening him - .use 7297", optional = true },
        { type = "complete", name = "Kill Morbent Fel", note = "This quest can be difficult. You may skip this step and come back at a higher level if you wish - .use 7297 - .mob Morbent Fel - .isOnQuest 55", zone = "Duskwood", x = 16.9, y = 33.4, quest = 55, objective = 1 },
        { type = "complete", name = "Kill Mor'Ladim. Loot him for his Skull", note = "Mor'Ladim hits very hard but moves quite slow. Try to kite him around any large trees if required - This quest can be difficult. You may skip this step and come back at a higher level if you wish - .unitscan Mor'Ladim", zone = "Duskwood", x = 19.59, y = 37.28, quest = 228, objective = 1 },
