        { type = "accept", name = "Talk to Bath'rah the Windwatcher", note = ".timer 40,The Summoning RP - Accepting this quest will summon |cRXP_ENEMY_Cyclonian. He hits fairly hard, but can be soloed. Be sure to check the video for pointers on how to do so - Click here for video reference (https://www.youtube.com/watch?v=BiuWeMSHEhA)", zone = "Alterac Mountains", x = 80.497, y = 66.919, npc = "Bath'rah the Windwatcher", quest = 1713, class = "WARRIOR" },
        { type = "complete", name = "Follow Bath'rah the Windwatcher to where he will summon Cyclonian", note = "Kill Cyclonian. Loot him for his Whirlwind Heart - Cyclonian hits fairly hard, but can be soloed. Be sure to check the video for pointers on how to do so - Click here for video reference (https://www.youtube.com/watch?v=BiuWeMSHEhA) - .isOnQuest 1713", zone = "Alterac Mountains", x = 80.65, y = 62.1, quest = 1713, objective = 1, class = "WARRIOR" },
        { type = "turnin", name = "Talk to Bath'rah the Windwatcher", note = ".isQuestComplete 1713", zone = "Alterac Mountains", x = 80.497, y = 66.919, npc = "Bath'rah the Windwatcher", quest = 1713, class = "WARRIOR" },
        { type = "turnin", name = "Talk to Bath'rah the Windwatcher", note = "The [Whirlwind Axe] is the best reward out of them all. However, if you do wish to choose a different weapon, it's only a small loss", zone = "Alterac Mountains", x = 80.497, y = 66.919, npc = "Bath'rah the Windwatcher", quest = 1792, class = "WARRIOR" },
