        { type = "turnin", name = "Click on the Keystone", note = "If you are still in a group, hand in this quest while with your party! |cRXP_ENEMY_Thenan, a level 42 Elite will spawn. You can either kill him or run away and reset him if you're solo - .isQuestComplete 652", zone = "Arathi Highlands", x = 36.07, y = 58.09, quest = 652 },
        { type = "accept", name = "Click on the Keystone", zone = "Arathi Highlands", x = 36.07, y = 58.09, quest = 653 },
        { type = "complete", name = "Kill Marez Cowl. Loot her for her Head", note = ".group 2 - Marez Cowl has 2 different spawn locations. One is on the high ground location, and the other is below behind the house. They are marked on your map - Cast [Eagle Eye] to try and find which location she is in - .unitscan Marez Cowl - .isOnQuest 684", zone = "Arathi Highlands", x = 29.599, y = 63.682, quest = 684, objective = 1, optional = true },
        { type = "complete", name = "Kill Otto and Lord Falconcrest. Loot them for their Heads", note = ".group 4 - .mob +Otto - .mob +Lord Falconcrest - .isOnQuest 685", zone = "Arathi Highlands", x = 26.026, y = 65.656, quest = 685, objective = 2 },
        { type = "complete", name = "Kill Marez Cowl. Loot her for her Head", note = ".solo - Marez Cowl has 2 different spawn locations. One is on the high ground location, and the other is below behind the house. They are marked on your map - Be careful as there are [Stealthed] level 36-37 elite Syndicate Prowlers in the area surrounding both her spawns - Cast [Eagle Eye] to try and find which location she is in - Skip this step if you're not confident in your ability to solo it - .unitscan Marez Cowl - .isOnQuest 684", zone = "Arathi Highlands", x = 29.624, y = 62.975, quest = 684, objective = 1, path = { { zone = "Arathi Highlands", x = 29.599, y = 63.682 }, { zone = "Arathi Highlands", x = 29.477, y = 64.149 } } },
        { type = "complete", name = "Kill Marez Cowl. Loot her for her Head", note = ".group 2 - Marez Cowl has 2 different spawn locations. One is on the high ground location, and the other is below behind the house. They are marked on your map - Be careful as there are [Stealthed] level 36-37 elite Syndicate Prowlers in the area surrounding both her spawns - Cast [Eagle Eye] to try and find which location she is in - .unitscan Marez Cowl - .isOnQuest 684", zone = "Arathi Highlands", x = 29.624, y = 62.975, quest = 684, objective = 1, path = { { zone = "Arathi Highlands", x = 29.599, y = 63.682 }, { zone = "Arathi Highlands", x = 29.477, y = 64.149 } } },
        { type = "complete", name = "Kill Boulderfist Shamans. Loot them for the Azure Agate. try to avoid fighting Boulderfist Maulers as much as possible", note = "Skip this step if you're not confident in your ability to solo it - .mob Boulderfist Shaman - .isOnQuest 694", zone = "Arathi Highlands", x = 20.21, y = 67.17, quest = 694, objective = 1, path = { { zone = "Arathi Highlands", x = 24.14, y = 61.85 }, { zone = "Arathi Highlands", x = 24.25, y = 64.97 }, { zone = "Arathi Highlands", x = 21.22, y = 66.52 } } },
        { type = "travel", name = "Escape Stromgarde through the hole in the wall in the south of the Ogre area. You can do this by jumping up on either side of the metal railings near the bent lamp post and running over to it", note = "Click here for video reference (https://youtu.be/5n9od9fcoz0?t=315)", zone = "Arathi Highlands", x = 21.98, y = 79.75, optional = true, path = { { zone = "Arathi Highlands", x = 24.57, y = 64.6 }, { zone = "Arathi Highlands", x = 21.25, y = 70.33 } } },
