        { type = "accept", name = "Talk to Professor Phizzlethorpe", note = "This will start an escort. If |cRXP_FRIENDLY_Professor Phizzlethorpe is not there, someone may already be doing it. Wait for him to return", zone = "Arathi Highlands", x = 33.869, y = 80.549, npc = "Professor Phizzlethorpe", quest = 665 },
        { type = "complete", name = "Escort Professor Phizzlethorpe into the small Cave", note = "Kill the Vengeful Surges that attack once inside. Be careful as they cast [Frost Nova] - Try to tag both of the Surges before they hit the Professor. This will make them not interrupt his roleplay and make the quest complete a lot faster - Follow Professor Phizzlethorpe back to the camp afterwards - .mob Vengeful Surge", zone = "Arathi Highlands", x = 33.856, y = 80.444, npc = "Professor Phizzlethorpe", quest = 665, objective = 1, path = { { zone = "Arathi Highlands", x = 35.74, y = 79.59 } } },
        { type = "accept", name = "Talk to Doctor Draxlegauge", zone = "Arathi Highlands", x = 33.856, y = 80.444, npc = "Doctor Draxlegauge", quest = 666 },
        { type = "note", name = "He can drop the [Tidal Charm] an extremely rare trinket that can be used to stun the target for 3 seconds", note = "Be on the lookout for the rare Prince Nazjak that can spawn in this area. - .itemcount 1404,<1 - .unitscan Prince Nazjak" },
        { type = "complete", name = "Loot the Elven Gems on the sea floor", note = "Equip your [Goggles of Gem Hunting] so the |cRXP_LOOT_Elven Gems show up on your minimap - Ensure you have buffed yourself with [Unending Breath] - Cast [Aquatic Form] once your Breath Bar gets low - .use 5996", quest = 666, objective = 1 },
        { type = "complete", name = "Kill Daggerspine Raiders and Daggerspine Sorceresses", note = "Be aware the |cRXP_ENEMY_Daggerspine Raiders will cast [Net] on you - Be mindful of your pet while doing this quest. It's pathing can get very buggy while fighting on the sunken ships - .mob +Daggerspine Raider - .mob +Daggerspine Sorceress - .use 5996", quest = 664, objective = 2 },
