        { type = "complete", name = "Kill Inferno Elementals, Blazing Elementals and Magma Elementals. Loot them for their Heart of Flames", note = "Kill Heavy War Golems and Magma Elementals. Loot them for their Golem Oils - Prioritize these two objectives - .mob +Inferno Elemental - .mob +Blazing Elemental - .mob +Magma Elemental - .mob +Magma Elemental - .mob +Heavy War Golem", zone = "Searing Gorge", x = 30.1, y = 76.16, quest = 3442, objective = 2, path = { { zone = "Searing Gorge", x = 43.83, y = 35.08 }, { zone = "Searing Gorge", x = 24.18, y = 54.52 }, { zone = "Searing Gorge", x = 28.54, y = 64.55 }, { zone = "Searing Gorge", x = 43.83, y = 35.08 }, { zone = "Searing Gorge", x = 24.18, y = 54.52 }, { zone = "Searing Gorge", x = 28.54, y = 64.55 }, { zone = "Searing Gorge", x = 30.1, y = 76.16 }, { zone = "Searing Gorge", x = 28.54, y = 64.55 }, { zone = "Searing Gorge", x = 24.18, y = 54.52 }, { zone = "Searing Gorge", x = 43.83, y = 35.08 }, { zone = "Searing Gorge", x = 43.83, y = 35.08 }, { zone = "Searing Gorge", x = 24.18, y = 54.52 }, { zone = "Searing Gorge", x = 28.54, y = 64.55 } } },
