        { type = "complete", name = "Kill Incendosaurs", note = ".mob Incendosaur", zone = "Searing Gorge", x = 45.41, y = 21.65, quest = 7727, objective = 1, path = { { zone = "Searing Gorge", x = 46.66, y = 42.48 }, { zone = "Searing Gorge", x = 51.67, y = 37.02 } } },
        { type = "travel", name = "Run back out of the cave, then follow the platform to the upper entrance of the cave", note = ".isOnQuest 7729,3443,7722,7701", zone = "Searing Gorge", x = 49.75, y = 45.82, path = { { zone = "Searing Gorge", x = 48.41, y = 41.08 }, { zone = "Searing Gorge", x = 47.94, y = 47.58 }, { zone = "Searing Gorge", x = 49.86, y = 45.97 } } },
        { type = "complete", name = "Kill Overseer Maltorius. Loot him for his Head", note = ".isOnQuest 7701 - Cast [Rain of Fire] to split pull him and then cast [Fear] on him repeatedly. Ensure you've cleared the area around you first - Remember to keep [Shadow Ward] on yourself as well - This quest can be quite difficult. Look for additional group members if required - Click here for video reference (https://youtu.be/k1eJ_LYUeIA) - .mob Overseer Maltorius", zone = "Searing Gorge", x = 40.81, y = 35.77, quest = 7701, objective = 1 },
        { type = "complete", name = "Loot the Secret Plans: Fiery Flux on the bench", note = ".isOnQuest 7722 - Pull all 3 mobs with your Pet then loot immediately - Pull all 3 mobs then cast [Psychic Scream] and loot immediately - Pull all 3 with a Voidwalker or Succubus (Seduce one of if using Succubus). You can also use [Fear] or [Howl of Terror] then loot immediately - Build up 25+ Rage, then cast [Intimidating Shout] on all 3 mobs then loot immediately - Only attempt this solo if you have 3/3 in [Improved Gouge] - Cast [Sap] on one guard, then position your self right next to the Secret Plans: Fiery Flux. Cast [Blind] on another then [Gouge] on the last one, ensuring you loot immediately after using [Gouge] - Cast [Polymorph] on |cRXP_ENEMY_Overseer Maltorius then [Frost Nova] the other 2 elites then immediately [Blink] in and loot - After looting, jump down below to the main floor OR the ledge to the right of the plans to evade any mobs you have aggro of - This quest can be quite difficult. Look for additional group members if required", zone = "Searing Gorge", x = 40.447, y = 35.739, quest = 7722, objective = 1 },
        { type = "accept", name = "Kill Dark Iron Taskmasters and Dark Iron Slavers. Loot them for their Thorium Plated Daggers and the [Grimesilt Outhouse Key]", note = "Any |cRXP_ENEMY_Dark Iron Dwarf may drop Thorium Plated Daggers and the [Grimesilt Outhouse Key] - Use the [|cRXP_LOOT_Grimesilt Outhouse Key] to start the quest - .mob +Dark Iron Taskmaster - .mob +Dark Iron Slaver - .mob +Dark Iron Taskmaster - .mob +Dark Iron Slaver - .collect 11818,1,4451 - .disablecheckbox - .use 11818", zone = "Searing Gorge", x = 43.18, y = 35.09, quest = 4451, objective = 1, path = { { zone = "Searing Gorge", x = 43.18, y = 35.09 }, { zone = "Searing Gorge", x = 43.54, y = 31.51 }, { zone = "Searing Gorge", x = 45.81, y = 25.66 } } },
        { type = "complete", name = "Kill Overseer Maltorius. Loot him for his Head", note = ".isOnQuest 7701 - Cast [Rain of Fire] to split pull him and then cast [Fear] on him repeatedly. Ensure you've cleared the area around you first - Remember to keep [Shadow Ward] on yourself as well - This quest can be quite difficult. Look for additional group members if required - Click here for video reference (https://youtu.be/k1eJ_LYUeIA) - .mob Overseer Maltorius", zone = "Searing Gorge", x = 40.81, y = 35.77, quest = 7701, objective = 1 },
        { type = "complete", name = "Loot the Secret Plans: Fiery Flux on the bench", note = ".isOnQuest 7722 - Pull all 3 mobs with your Pet then loot immediately - Pull all 3 mobs then cast [Psychic Scream] and loot immediately - Pull all 3 with a Voidwalker or Succubus (Seduce one of if using Succubus). You can also use [Fear] or [Howl of Terror] then loot immediately - Build up 25+ Rage, then cast [Intimidating Shout] on all 3 mobs then loot immediately - Only attempt this solo if you have 3/3 in [Improved Gouge] - Cast [Sap] on one guard, then position your self right next to the Secret Plans: Fiery Flux. Cast [Blind] on another then [Gouge] on the last one, ensuring you loot immediately after using [Gouge] - Cast [Polymorph] on |cRXP_ENEMY_Overseer Maltorius then [Frost Nova] the other 2 elites then immediately [Blink] in and loot - After looting, jump down below to the main floor OR the ledge to the right of the plans to evade any mobs you have aggro of - This quest can be quite difficult. Look for additional group members if required", zone = "Searing Gorge", x = 40.447, y = 35.739, quest = 7722, objective = 1 },
